WITH UserBadgeStats AS (
    SELECT
        u.Id AS UserId,
        u.DisplayName,
        COUNT(CASE WHEN b.Class = 1 THEN 1 END) AS GoldBadges,
        COUNT(CASE WHEN b.Class = 2 THEN 1 END) AS SilverBadges,
        COUNT(CASE WHEN b.Class = 3 THEN 1 END) AS BronzeBadges,
        COALESCE(SUM(p.Score),0) AS TotalPostScores,
        ROW_NUMBER() OVER(PARTITION BY u.Location ORDER BY COUNT(CASE WHEN b.Class = 1 THEN 1 END) DESC, SUM(p.Score) DESC NULLS LAST) AS RankInLocation
    FROM
        Users u
        LEFT JOIN Badges b ON u.Id = b.UserId
        LEFT JOIN Posts p ON p.OwnerUserId = u.Id AND p.PostTypeId IN (1,2)
    WHERE u.Location IS NOT NULL
    GROUP BY u.Id, u.DisplayName, u.Location
),
